import { Duration } from "@moq/clock";
import * as Catalog from "@moq/hang/catalog";
import * as Container from "@moq/hang/container";
import * as Moq from "@moq/net";
import { Broadcast } from "../../../../../js/watch/src/broadcast";
import { Sync } from "../../../../../js/watch/src/sync";
import { Decoder } from "../../../../../js/watch/src/video/decoder";
import { Source } from "../../../../../js/watch/src/video/source";

/** One real open-GOP access unit generated by ffmpeg. */
export type Packet = { group: number; timestamp: number; data: string };

declare global {
	interface Window {
		runRecovery(packets: Packet[]): Promise<{ submitted: number[]; decoded: number; software: boolean }>;
	}
}

window.runRecovery = async (packets) => {
	const Native = window.VideoDecoder;
	const codecs: VideoDecoder[] = [];
	const submitted: number[] = [];
	let decoded = 0;
	let software = true;
	let failed: Error | undefined;
	let ended!: () => void;
	const inputDone = new Promise<void>((resolve) => {
		ended = resolve;
	});
	const next = Container.Consumer.prototype.next;
	Container.Consumer.prototype.next = async function () {
		const item = await next.call(this);
		if (!item) ended();
		return item;
	};
	window.VideoDecoder = class extends Native {
		constructor(init: VideoDecoderInit) {
			super({
				output(frame) {
					decoded++;
					init.output(frame);
				},
				error(error) {
					failed = error;
					ended();
					init.error(error);
				},
			});
			codecs.push(this);
		}
		override configure(config: VideoDecoderConfig) {
			const softwareConfig = { ...config, hardwareAcceleration: "prefer-software" as const };
			software &&= softwareConfig.hardwareAcceleration === "prefer-software";
			super.configure(softwareConfig);
		}
		override decode(chunk: EncodedVideoChunk) {
			submitted.push(chunk.timestamp);
			super.decode(chunk);
		}
	};
	const origin = new Moq.Origin.Producer();
	const name = Moq.Path.from("open-gop");
	const route = origin.route(name);
	const track = route.broadcast.createTrack("video", { timescale: Moq.Time.Timescale.MICRO, maxAge: null });
	if (!track) throw new Error("the track already exists");
	const config = Catalog.VideoConfigSchema.parse({
		codec: "avc1.64001f",
		container: { kind: "legacy" },
		codedWidth: 160,
		codedHeight: 96,
	});
	const broadcast = new Broadcast({
		origin,
		name,
		catalogFormat: "manual",
		catalog: { video: { renditions: { video: config } } },
	});
	const source = new Source({ broadcast });
	// A rejected codec probe selects no rendition, so nothing else would end the run.
	source.out.error.subscribe((error) => {
		if (!error) return;
		failed = error;
		ended();
	});
	const sync = new Sync({ delay: Duration.millis(0), lookahead: Duration.millis(10_000) });
	const decoder = new Decoder({ source, sync });
	try {
		// The player joins live, reading only groups written after it subscribes, so publish once it asks
		// for a first group, as a live publisher does. Group 1 is then the join and group 4 the later gap.
		const demand = track.demand();
		while (!demand.refresh.peek() && !failed) await Promise.race([demand.refresh.changed(), inputDone]);
		// Every group is written before the decoder reads past the first, so none may go stale.
		let group: Moq.Group.Producer | undefined;
		// A group's transport times never decrease, so a leading picture rides at the newest so far
		// while its payload keeps its own presentation time, as `Container.Legacy.Producer` does.
		let newest = 0;
		for (const packet of packets) {
			if (group?.start !== BigInt(packet.group)) {
				group?.finish();
				group = track.createGroup(BigInt(packet.group));
				newest = packet.timestamp;
			}
			newest = Math.max(newest, packet.timestamp);
			const timestamp = Duration.micros(packet.timestamp);
			const payload = Uint8Array.from(atob(packet.data), (c) => c.charCodeAt(0));
			group.writeFrame({
				payload: Container.Legacy.encodeFrame(payload, timestamp),
				timestamp: Moq.Time.Timestamp.fromMicros(newest),
			});
		}
		group?.finish();
		track.finish();
		track.close();
		await inputDone;
		if (failed) throw failed;
		for (const codec of codecs) await codec.flush();
		if (failed) throw failed;
		return { submitted, decoded, software };
	} finally {
		decoder.close();
		source.close();
		sync.close();
		broadcast.close();
		origin.close();
		window.VideoDecoder = Native;
		Container.Consumer.prototype.next = next;
	}
};
